"use strict";

class ReferenceController {
	/*@ngInject*/
	constructor($scope, $location, $appLoader, pageContext, ReferenceRepository, editReferenceModal) {
		this.language = language;
		this.ReferenceRepository = ReferenceRepository;
		this.$appLoader = $appLoader;
		this.$scope = $scope;
		this.modalWindow = editReferenceModal

		$scope.language = language;

		pageContext.title = language.Generic.MenuFolders.kFNReferenceBooks;
		pageContext.parent = null;

		$scope.referenceType = null;
		let self = this;

		$scope.$watch(() => $scope.referenceType, (newReferenceType) => {
			if(!newReferenceType) return;
			//updateButton.isHidden = newReferenceType.refType == "UserInfoListItems";
			self.referenceType = newReferenceType;
			self.search = "";
			self.updateTable($scope);

			$location.search({
				'refType': newReferenceType.refType,
				'parameterId': newReferenceType.parameterId,
			});

			return newReferenceType;
		});

		ReferenceRepository.getReferenceTypes()
			.then(response => $scope.referenceTypes = response.sort(o => o.parameterId))
			.then(references => {
				let defaultItem = angular.extend({refType: 'ExamTypes'}, $location.search());
				$scope.referenceType = _.findWhere(references, defaultItem);
			})
			.then(() => $appLoader.hide());

		// Описание кнопок
		let buttonId = 0;
		let addButton = {
			id: buttonId++,
			class: 'btn-info',
			action: () => self.create(),
			icon: "glyphicon-plus-sign",
			text: language.Generic.Common.kAdd,
			isEnabled: true,
			checkEnabled: () => true,
			systemName: "Create",
			isHidden: false
		};
		/* // убрать кнопку "Редактирование", т.к есть ссылка на редактирование (тогда по стилю будет единообразно, как в локальных справочниках)
		let updateButton = {
			id: buttonId++,
			class: 'btn-info',
			action: () => self.update(),
			icon: "glyphicon-pencil",
			text: language.Generic.Common.kEdit,
			isEnabled: false,
			checkEnabled: () => {
				let selected = self.getSelected();
				return selected.length == 1
					&& this.checkEditEnabled(selected[0]);
			},
			systemName: "Edit",
			isHidden: false,
		}; 
		*/
		let replaceButton = {
			id: buttonId++,
			class: 'btn-info',
			action: () => self.replace(),
			icon: "glyphicon-refresh",
			text: language.Generic.ServAdmin.kReplace,
			isEnabled: false,
			checkEnabled: () => {
				let selected = self.getSelected();
				return selected.length > 0
					&& selected.findIndex(o => o.isUsed == "System") < 0;
			},
			systemName: "Replace",
			isHidden: false,
		}

		let deleteButton = {
			id: buttonId++,
			class: "btn-danger",
			action: () => self.delete(),
			icon: "glyphicon-minus-sign",
			text: language.Generic.Common.kRemove,
			isEnabled: false,
			checkEnabled: () => {
				let selected = self.getSelected();
				return selected.length > 0
					&& (selected.findIndex(o => o.isUsed != "Free") < 0 || selected.every(o => o.numberOfUses === 0));
			},
			systemName: "Delete",
			isHidden: false,
		};

		let clearButton = {
			id: buttonId++,
			class: 'btn-info',
			action: () => self.clearAll(),
			icon: "glyphicon-unchecked",
			text: language.Generic.Buttons.kClearAll,
			isEnabled: false,
			checkEnabled: () => self.getSelected().length > 0,
			systemName: "ClearSelected",
			isHidden: false,
		}

		$scope.buttons = [addButton, replaceButton, deleteButton, clearButton];
		$scope.$watch(() => self.getSelected()[0], () => {
			$scope.buttons.forEach(button => button.isEnabled = button.checkEnabled());
		});
		// Закончилось описание кнопок
	}

	getSelected() {
		return this.reference && this.reference.data
			&& this.reference.data.filter(o => o.isSelected)
			|| [];
	}

	checkEditEnabled(data) {
		let isUsed = data.isUsed;
		return (isUsed && this.updateEnabledOnStatus.indexOf(isUsed) >= 0) || !isUsed;
	}

	updateTable($scope) {
		let self = this;
		self.$appLoader.show();
		return this.ReferenceRepository.getReference(self.referenceType.refType, self.referenceType.parameterId)
			.then(response => {
				self.clearAll();

				response.data = response.data;//.sort((a,b) => (a['order'] || 0) - (b['order'] || 0));
				let permissions = response.permitedActions.split(', ');
				permissions.push('ClearSelected');
				self.updateEnabledOnStatus = response.type.isEditableInStatus;
				$scope.buttons.forEach(button => {
					button.isHidden = permissions.indexOf(button.systemName) < 0;
				});

				return response;
			})
			.then(response => $scope.reference = self.reference = response)
			.then(() => self.$appLoader.hide());
	}

	showModal(data) {
		let self = this;
		return this.modalWindow.showEdit(data, self.referenceType.name, self.referenceType);
	}

	create() {
		this.showUpdateWindow(this.reference.fields);
	}

	update() {
		let selected = this.getSelected();

		const prepareDate = (line) => {
			let data = angular.copy(this.reference.fields);
			for(let index in data){
				let prop = data[index];
				prop.value = line[prop.systemName];
			}
			return data;
		}
		let data = prepareDate(selected[0]);
		this.showUpdateWindow(data);
	}

	showUpdateWindow(model) {
		let self = this;
		return this.showModal(model)
			.finally(() => self.updateTable(self.$scope));
	}

	editLink(data) {
		if(!this.checkEditEnabled(data)) return;
		return this.showUpdateWindow(data);
	}

	replace(){
		let getField = (fields, name) => fields.find(o => o.systemName == name);
		let ids = this.getSelected().map(line => line.id);
		let data = this.reference.data.filter(o => ids.indexOf(o.id) >= 0);
		let model = {
			data: data,
			fields: angular.copy(this.reference.fields),
			pageSize: 10,
			isReplaceable: false,
			noDataMessage: null,
			type: angular.copy(this.reference.type),
			sourceData: this.reference.data
		}

		getField(model.fields, "id").isHidden = false;
		this.modalWindow.showReplace(model, this.referenceType.name)
			.then(result => {
				this.$appLoader.show();
				let type = this.referenceType.refType;
				let parameterId = this.referenceType.parameterId;
				let replaceById = result.id;
				let ids = data.map(o => o.id).filter(o => o != replaceById);
				if(ids.length == 0) return;

				this.search = "";
				return this.ReferenceRepository.replaceReference(type, parameterId, ids, replaceById);
			})
			.finally(() => {
				this.$appLoader.hide();
				let updateResult = this.updateTable(this.$scope);
				return updateResult;
			});
	}

	delete() {
		let self = this;

		let type = self.referenceType.refType;
		let selected = this.getSelected();
		let ids = selected.map(line => line.id);
		let mainField = self.reference.fields.find(f => f.isMain).systemName;
		let nameList = selected.map(line => line[mainField]);
		let message = language.Generic.ServAdmin.kConfirmDeleteChosenList;

		message += '<ul>';
		for(let index in nameList){
			message += `<li>${nameList[index]}</li>`;
		}
		message += '</ul>';

		message += language.Generic.ServAdmin.kConfirmDeleteCount + ": " + nameList.length + ". "

		message += self.reference.type.messages.deleteConfirm || language.Generic.Common.kMsgAreYouSure;

		return $.show.confirmation(message).then(() => {
			self.$appLoader.show();
			return self.ReferenceRepository.deleteReference(type, ids)
				.finally(() => {
					self.$appLoader.hide();
					let updateResult = self.updateTable(self.$scope);
					return updateResult;
				});
		});
	}

	onSelect(data) {
		let id = data.find(f => f.systemName == "id").value;
		let item = this.reference.data.find(o => o.id == id);
		if (item.isUsed == "Used" || item.numberOfUses > 0) {
			this.clearAll();
		}
		if ((item.isUsed == "Free" && this.getSelected().findIndex(o => o.isUsed == "Used") >= 0) ||
			(item.numberOfUses == 0 && this.getSelected().findIndex(o => o.numberOfUses > 0) >= 0)) {
			this.clearAll();
		}
		item.isSelected = !item.isSelected;
	}

	clearAll() {
		let list = this.reference && this.reference.data;
		for(let index in list)
			list[index].isSelected = false;
	}

}

class EditController {
	constructor($scope, $uibModalInstance, model, title, $appLoader, referenceType, ReferenceRepository) {
		this.ReferenceRepository = ReferenceRepository;
		this.$appLoader = $appLoader;
		this.referenceType = referenceType;
		this.model = model;
		let id = this.model && this.model.find(o => o["systemName"] == "id");
		let status = this.model && this.model.find(o => o["systemName"] == "isUsed");
		this.isEdit = id && !!id.value;
		this.status = status && status.value || "Free";
		let buttonId = 0;
		$scope.buttons = [
			{
				id: buttonId++,
				class: 'btn-primary',
				action: () => {
					if (!this.validate())
						return false;
					this.save().then((saved) => {
						$uibModalInstance.close(this.model);
					});
				},
				icon: "glyphicon-floppy-save",
				text: language.Generic.Buttons.kSave,
				disabled: () => !this.validate()
			},
			{
				id: buttonId++,
				class: "btn-default",
				action: () => $uibModalInstance.dismiss('cancel'),
				icon: "glyphicon-ban-circle",
				text: language.Generic.Buttons.kCancel,
				disabled: () => false
			}
		];

		$scope.title = title;
	}

	validate() {
		// Проверка поля по одному валидатору. Если прошёл проверку, то true
		const valueSingleValidate = (value, validator) => (new RegExp(validator.condition).test(value));
		// Проверка поля всеми валидаторами, если прошёл проверку, то true
		const valueValidate = (value, validators) => !validators.find(validator => !valueSingleValidate(value == undefined ? "" : value, validator));
		// Проверка всех полей, всеми валидаторами, если видимые поля прошли проверку, то true
		let result = this.model
			.filter(field => !field.isHidden)
			.filter(field => field.validators.length > 0)
			.filter(field => !this.isEdit || field.isEditableInStatus.indexOf(this.status) >= 0) // Поле можно редактировать в данном статусе
			.filter(field => !valueValidate(field.value, field.validators));
		return result.length == 0;
	}

	getValueBySystemName(systemName) {
		return this.model.find(field => field.systemName == systemName).value;
	}

	save() {
		let result = {};
		for (let index in this.model) {
			let prop = this.model[index];
			result[prop.systemName] = prop.value;
		}

		this.$appLoader.show();
		let type = this.referenceType.refType;
		let parameterId = this.referenceType.parameterId;
		return this.ReferenceRepository.saveReference(type, parameterId, result)
			.finally(() => this.$appLoader.hide());
	}
}

EditController.$inject = ["$scope", "$uibModalInstance", "model", "title", "$appLoader", "referenceType", "ReferenceRepository"];

class ReplaceController {
	constructor($uibModalInstance, model, title) {
		this.language = language;
		this.model = model;
		let mainField = model.fields.find(f => f.isMain).systemName;
		let nameList = model.data.map(line => line[mainField]);

		let message = language.Generic.Common.kReplacementConfirmationMessage;

		message += '<ul>';
		for (let index in nameList) {
			message += `<li>${nameList[index]}</li>`;
		}
		message += '</ul>';

		let buttonId = 0;
		this.buttons = [
			{
				id: buttonId++,
				class: 'btn-primary',
				action: () => $.show.confirmation(message.replace("{0}", this._result.fields[1].value)).then(() => {
					$uibModalInstance.close(this.model.sourceData.find(o => o.id == this._result.id));
				}),
				icon: "glyphicon-floppy-save",
				text: language.Generic.ServAdmin.kReplace,
				disabled: () => !this._result
			},
			{
				id: buttonId++,
				class: "btn-default",
				action: () => $uibModalInstance.dismiss('cancel'),
				icon: "glyphicon-ban-circle",
				text: language.Generic.Buttons.kCancel,
				disabled: () => false
			}
		];

		this.title = title;
		this.formatedData = [];
		this._result = null;
	}

	get result() {
		return this._result;
	}

	set result(value) {
		if(this._result != value)
			this._result = value;
	}

	init() {
		let fields = this.model.fields
			.filter(field => !field.isHidden);

		for (let index in this.model.sourceData) {
			let data = this.model.sourceData[index];
			if (this.model.data.indexOf(data) == -1)
				this.formatedData.push(this.map(data, fields));
		}
	}

	getMain(data){
		return data && data.find(o => o.isMain).value;
	}

	map(data, fields) {
		let result = fields.map(o => {
			return {
				name: o.uiName || o.systemName,
				value: this.getText(data, o),
				isMain: o.isMain
			}
		})
		.filter(o => !!o.value);

		return {
			id: data.id,
			fields: result
		};
	}

	getText(line, column) {
		const toCamelCase = (str) => str && `${str[0].toLocaleLowerCase()}${str.slice(1)}`;

		let value = line[column.systemName];

		if(column.type === "Date"){
			let date = new Date(value);
			return dateUtils.date2str(date);
		}

		if(column.availableValues){
			let cameledValue = typeof(value) === "string"
				? toCamelCase(value)
				: value;
			let data = column.availableValues[cameledValue];
			return !!data ? data.name : '-';
		}
		return value;
	}
}

ReplaceController.$inject = ["$uibModalInstance", "model", "title"];


let modalWindowFactory = ($uibModal) => {
	let editWindowConfig = {
		templateUrl: "/static/dist/app/admin/reference/editModelTemplate.html",
		controller: EditController,
		controllerAs: "$ctrl",
		backdrop: 'static',
		size: 'md',
	}

	let replaceWindowConfig = {
		templateUrl: "/static/dist/app/admin/reference/replaceTemplate.html",
		controller: ReplaceController,
		controllerAs: "$ctrl",
		backdrop: 'static',
		size: 'lg',
	}

	return {
		showEdit: (model, title, referenceType) => {
			let resolve = {
				resolve: {
					model: () => model,
					title: () => title,
					referenceType: () => referenceType
				}
			};

			return $uibModal.open(angular.extend(resolve, editWindowConfig)).result;
		},

		showReplace: (model, title) => {
			let resolve = {
				resolve: {
					model: () => model,
					title: () => title
				}
			};

			return $uibModal.open(angular.extend(resolve, replaceWindowConfig)).result;
		}
	}
}

module.exports = { ReferenceController, editReferenceModal: modalWindowFactory};


