"use strict";

import { BaseRepository } from "approot/global/repository.js";

class ReferenceRepository extends BaseRepository {
	getReference(type, parameterId){
		let url = parameterId
			? `/webapi/reference/${type}?parameterId=${parameterId}`
			: `/webapi/reference/${type}`
		return this.$http.get(url)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	getReferenceTypes(){
		return this.$http.get(`/webapi/refbook`)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	saveReference(type, parameterId, referenceData) {
		let uri = parameterId
			? `/webapi/reference/${type}?parameterId=${parameterId}`
			: `/webapi/reference/${type}`
		return this.$http.post(uri, referenceData)
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	deleteReference(type, ids) {
		return this.$http.delete(`/webapi/refbook/${type}`, {params: {id: ids}})
			.then(this.handleResponse)
			.catch(this.handleError);
	}

	replaceReference(type, parameterId, ids, replaceById) {
		let options = {
			params: {
				ids: ids,
				replaceById: replaceById,
				parameterId: parameterId,
			}
		};
		return this.$http.post(`/webapi/refbook/${type}/replacement`, null, options)
			.then(this.handleResponse)
			.catch(this.handleError);
	}
}

module.exports = {ReferenceRepository};


