
const module = angular.module("irtech.netcity.admin.reference",
	[
		"ngRoute", "ngSanitize","ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

import { ReferenceRepository } from "./repository.js";
import { ReferenceController, editReferenceModal } from "./referenceController.js";

module
	.factory('ReferenceRepository', ($http, $dialogs, $alerts, $q) => new ReferenceRepository($http, $dialogs, $alerts, $q))
	.factory("editReferenceModal", editReferenceModal)
	.controller("ReferenceCtrl", ReferenceController)
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.otherwise({
				templateUrl: '/static/dist/app/admin/reference/referenceTemplate.html',
				controller: "ReferenceCtrl",
				reloadOnSearch: false,
				controllerAs: "$ctrl"
			});

		$locationProvider.hashPrefix("");
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});


